{"path":"/workspace/source/packages/contracts/src/erasure.ts","command":"create","file_text":"/** Stable anonymized identity retained on financial records after customer erasure. */
export function erasedCustomerEmail(customerId: string): string {
  return `erased-${customerId}@erased.invalid`;
}

export function erasedCustomerName(): string {
  return 'Erased Customer';
}

export function erasedExternalReference(customerId: string): string {
  return `erased-${customerId}`;
}

export function anonymizedCustomerSnapshot(
  customerId: string,
  extras: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    ...extras,
    id: customerId,
    email: erasedCustomerEmail(customerId),
    name: erasedCustomerName(),
    phone: null,
    external_reference: erasedExternalReference(customerId),
    status: 'erased',
    metadata: {},
  };
}

export const ERASURE_ERROR_CODES = {
  CLEANUP_FAILED: 'cleanup_failed',
  CUSTOMER_NOT_FOUND: 'customer_not_found',
} as const;
"}

{"path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","command":"create","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  max_attempts: number;
  idempotency_key: string | null;
  last_error: string | null;
  progress: Record<string, unknown>;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function toErasureResponse(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async findCustomer(merchantId: string, customerId: string): Promise<{ id: string; status: string } | undefined> {
    const result = await pool.query<{ id: string; status: string }>(
      `SELECT id,status FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findByIdempotencyKey(
    client: pg.PoolClient,
    merchantId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests
       WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE`,
      [merchantId, idempotencyKey],
    );
    return result.rows[0];
  }

  async create(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,status,idempotency_key)
       VALUES($1,$2,'pending',$3)
       ON CONFLICT(merchant_id,customer_id) DO UPDATE
         SET updated_at=customers.erasure_requests.updated_at
       RETURNING *`,
      [merchantId, customerId, idempotencyKey],
    );
    return result.rows[0]!;
  }

  async claimNext(workerId: string, leaseSeconds = 120): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, updated_at=now(), last_error=NULL,
           progress=COALESCE(progress,'{}'::jsonb) || jsonb_build_object('lockedBy',$1::text,'lockedAt',now())
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed')
           AND attempts < max_attempts
           AND (
             status='pending'
             OR (status='failed' AND updated_at <= now() - interval '2 seconds')
           )
         ORDER BY updated_at, created_at
         FOR UPDATE SKIP LOCKED
         LIMIT 1
       )
       RETURNING *`,
      [workerId],
    );
    return result.rows[0];
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), updated_at=now(), last_error=NULL,
           progress=COALESCE(progress,'{}'::jsonb) || jsonb_build_object('completed',true)
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(client: pg.PoolClient, requestId: string, errorCode: string, attempts: number, maxAttempts: number): Promise<void> {
    const dead = attempts >= maxAttempts;
    await client.query(
      `UPDATE customers.erasure_requests
       SET status=$2, last_error=$3, updated_at=now(),
           progress=COALESCE(progress,'{}'::jsonb) || jsonb_build_object('lastFailure', $3::text)
       WHERE id=$1`,
      [requestId, dead ? 'failed' : 'failed', errorCode],
    );
  }

  async saveProgress(client: pg.PoolClient, requestId: string, progress: Record<string, unknown>): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET progress=COALESCE(progress,'{}'::jsonb) || $2::jsonb, updated_at=now()
       WHERE id=$1`,
      [requestId, JSON.stringify(progress)],
    );
  }

  async ensureTombstone(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO customers.erasure_tombstones(merchant_id,customer_id,erasure_request_id)
       VALUES($1,$2,$3) ON CONFLICT DO NOTHING`,
      [merchantId, customerId, requestId],
    );
  }

  async isErased(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async isErasedTx(client: pg.PoolClient, merchantId: string, customerId: string): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }
}
"}

{"path":"/workspace/source/apps/customer-service/src/erasure-service.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import type pg from 'pg';
import { Redis } from 'ioredis';
import { v4 as uuid } from 'uuid';
import {
  anonymizedCustomerSnapshot,
  erasedCustomerEmail,
  erasedCustomerName,
  erasedExternalReference,
  ERASURE_ERROR_CODES,
} from '../../../packages/contracts/src/erasure.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureRepository,
  toErasureResponse,
  type ErasureRequestResponse,
  type ErasureRequestRow,
} from './erasure-repository.js';

const ERASED_PLACEHOLDER = '[erased]';

export class ErasureService {
  private redis: Redis | undefined;

  constructor(private readonly repository = new ErasureRepository()) {}

  private getRedis(): Redis {
    this.redis ??= new Redis(config().REDIS_URL);
    return this.redis;
  }

  async createRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: ErasureRequestResponse }> {
    if (idempotencyKey.length < 8 || idempotencyKey.length > 200) {
      throw Object.assign(new Error('invalid idempotency key'), { statusCode: 422 });
    }

    const customer = await this.repository.findCustomer(merchantId, customerId);
    if (!customer) {
      throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    }

    return transaction(async (client) => {
      const byKey = await this.repository.findByIdempotencyKey(client, merchantId, idempotencyKey);
      if (byKey) {
        if (byKey.customer_id !== customerId) {
          throw Object.assign(new Error('idempotency key reused with different customer'), { statusCode: 409 });
        }
        if (byKey.status === 'failed') {
          await client.query(
            `UPDATE customers.erasure_requests
             SET status='pending', updated_at=now(), last_error=NULL
             WHERE id=$1 AND status='failed'`,
            [byKey.id],
          );
          const refreshed = await this.repository.findById(merchantId, byKey.id);
          return { status: 202, body: toErasureResponse(refreshed ?? byKey) };
        }
        return { status: 202, body: toErasureResponse(byKey) };
      }

      const existing = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests
         WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      if (existing.rows[0]) {
        const row = existing.rows[0];
        if (row.status === 'failed') {
          await client.query(
            `UPDATE customers.erasure_requests
             SET status='pending', updated_at=now(), last_error=NULL
             WHERE id=$1`,
            [row.id],
          );
          const refreshed = await this.repository.findById(merchantId, row.id);
          return { status: 202, body: toErasureResponse(refreshed ?? row) };
        }
        return { status: 202, body: toErasureResponse(row) };
      }

      const created = await this.repository.create(client, merchantId, customerId, idempotencyKey);
      await client.query(
        `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
         VALUES($1,'api_key','erasure_request',$2,'erasure.requested',$3,$4)`,
        [merchantId, created.id, { customerId }, uuid()],
      );
      return { status: 202, body: toErasureResponse(created) };
    });
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toErasureResponse(row) : undefined;
  }

  async processNext(workerId: string): Promise<boolean> {
    const claim = await this.repository.claimNext(workerId);
    if (!claim) return false;
    try {
      await this.runCleanup(claim);
      return true;
    } catch (error) {
      const code = error instanceof Error && error.message.startsWith('erasure_')
        ? error.message
        : ERASURE_ERROR_CODES.CLEANUP_FAILED;
      await transaction(async (client) => {
        await this.repository.markFailed(client, claim.id, code, claim.attempts, claim.max_attempts);
      });
      return true;
    }
  }

  private async runCleanup(request: ErasureRequestRow): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId, id: requestId } = request;
    const progress = { ...(request.progress ?? {}) };

    // Capture contact destinations before wiping customer PII so mail can be purged.
    const destinations = await this.collectDestinations(merchantId, customerId);

    await transaction(async (client) => {
      await this.repository.ensureTombstone(client, merchantId, customerId, requestId);
      await this.repository.saveProgress(client, requestId, { ...progress, tombstone: true });
    });

    if (!progress.customerCore) {
      await transaction(async (client) => {
        await this.scrubCustomerCore(client, merchantId, customerId);
        await this.repository.saveProgress(client, requestId, { customerCore: true });
      });
      progress.customerCore = true;
    }

    if (!progress.payments) {
      await transaction(async (client) => {
        await this.scrubPayments(client, merchantId, customerId);
        await this.repository.saveProgress(client, requestId, { payments: true });
      });
      progress.payments = true;
    }

    if (!progress.operations) {
      await transaction(async (client) => {
        await this.scrubOperations(client, merchantId, customerId);
        await this.repository.saveProgress(client, requestId, { operations: true });
      });
      progress.operations = true;
    }

    if (!progress.provider) {
      await transaction(async (client) => {
        await this.scrubProvider(client, merchantId, customerId);
        await this.repository.saveProgress(client, requestId, { provider: true });
      });
      progress.provider = true;
    }

    if (!progress.documents) {
      await this.scrubDocuments(merchantId, customerId);
      await transaction(async (client) => {
        await this.repository.saveProgress(client, requestId, { documents: true });
      });
      progress.documents = true;
    }

    if (!progress.projections) {
      await this.scrubProjections(merchantId, customerId);
      await transaction(async (client) => {
        await this.repository.saveProgress(client, requestId, { projections: true });
      });
      progress.projections = true;
    }

    if (!progress.mail) {
      for (const destination of destinations) {
        if (!destination || destination.endsWith('@erased.invalid') || destination === ERASED_PLACEHOLDER) continue;
        await deleteMailpitMessagesForRecipient(destination);
      }
      await transaction(async (client) => {
        await this.repository.saveProgress(client, requestId, { mail: true });
      });
      progress.mail = true;
    }

    await transaction(async (client) => {
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId: uuid(),
        payload: { customerId, erasureRequestId: requestId },
      });
      await client.query(
        `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
         VALUES($1,'system','erasure_request',$2,'erasure.completed',$3,$4)`,
        [merchantId, requestId, { customerId }, uuid()],
      );
      await this.repository.markCompleted(client, requestId);
    });
  }

  private async collectDestinations(merchantId: string, customerId: string): Promise<string[]> {
    const destinations = new Set<string>();
    const customer = await this.repository.findCustomer(merchantId, customerId);
    // findCustomer only returns id/status — load full PII if still present.
    const full = await transaction(async (client) => {
      const result = await client.query<{ email: string | null; phone: string | null }>(
        `SELECT email,phone FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      return result.rows[0];
    });
    if (full?.email) destinations.add(full.email);
    if (full?.phone) destinations.add(full.phone);

    const contacts = await transaction(async (client) => {
      const result = await client.query<{ value: string }>(
        `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      return result.rows;
    });
    for (const row of contacts) destinations.add(row.value);

    const prefs = await transaction(async (client) => {
      const result = await client.query<{ destination: string }>(
        `SELECT destination FROM operations.notification_preferences
         WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      return result.rows;
    });
    for (const row of prefs) destinations.add(row.destination);

    const emails = await transaction(async (client) => {
      const result = await client.query<{ destination: string }>(
        `SELECT destination FROM operations.email_deliveries
         WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      return result.rows;
    });
    for (const row of emails) destinations.add(row.destination);

    const refunds = await transaction(async (client) => {
      const result = await client.query<{ customer_email: string | null }>(
        `SELECT DISTINCT r.customer_email FROM payments.refunds r
         JOIN payments.payment_intents p ON p.id=r.payment_intent_id
         WHERE p.merchant_id=$1 AND p.customer_id=$2 AND r.customer_email IS NOT NULL`,
        [merchantId, customerId],
      );
      return result.rows;
    });
    for (const row of refunds) if (row.customer_email) destinations.add(row.customer_email);

    void customer;
    return [...destinations];
  }

  private async scrubCustomerCore(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const email = erasedCustomerEmail(customerId);
    const name = erasedCustomerName();
    const externalReference = erasedExternalReference(customerId);

    await client.query(
      `UPDATE customers.customers
       SET email=$3, name=$4, phone=NULL, external_reference=$5, metadata='{}'::jsonb,
           status='erased', version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, email, name, externalReference],
    );

    await client.query(
      `DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token='erased', billing_name=NULL, billing_address=NULL, status='erased',
           brand=NULL, last4=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Support tickets may be shared across customers; scrub only this customer's authored content
    // and detach the participant link without deleting tickets other customers still need.
    await client.query(
      `UPDATE customers.support_messages
       SET body=$3, attachments='[]'::jsonb, author_id=NULL
       WHERE merchant_id=$1 AND author_type='customer' AND author_id=$2`,
      [merchantId, customerId, ERASED_PLACEHOLDER],
    );
    await client.query(
      `DELETE FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );

    // Import artifacts contain PII; drop manifests/objects later, clear DB pointers here.
    await client.query(
      `UPDATE customers.customer_imports SET source='erased' WHERE merchant_id=$1 AND object_key LIKE $2`,
      [merchantId, `${merchantId}/imports/%`],
    );

    await client.query(
      `UPDATE platform.audit_logs
       SET metadata=$3
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2`,
      [merchantId, customerId, { erased: true }],
    );
  }

  private async scrubPayments(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const snapshot = anonymizedCustomerSnapshot(customerId);
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=$3, description=CASE
         WHEN description IS NULL THEN NULL
         ELSE $4
       END, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, snapshot, ERASED_PLACEHOLDER],
    );

    await client.query(
      `UPDATE payments.refunds r
       SET customer_email=$3
       FROM payments.payment_intents p
       WHERE r.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId, erasedCustomerEmail(customerId)],
    );

    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=$3
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, snapshot],
    );

    // Dispute evidence may contain customer-submitted PII.
    await client.query(
      `UPDATE payments.disputes d
       SET evidence=$3
       FROM payments.payment_intents p
       WHERE d.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId, { erased: true }],
    );

    // Payment attempt payloads can include customer identifiers from the create request.
    await client.query(
      `UPDATE payments.payment_attempts a
       SET request_payload = COALESCE(a.request_payload,'{}'::jsonb) - 'description'
             || jsonb_build_object('customerId', $2::text),
           response_payload = CASE
             WHEN a.response_payload IS NULL THEN NULL
             ELSE jsonb_build_object('redacted', true)
           END,
           failure_message = CASE WHEN a.failure_message IS NULL THEN NULL ELSE $3 END
       FROM payments.payment_intents p
       WHERE a.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId, ERASED_PLACEHOLDER],
    );
  }

  private async scrubOperations(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE operations.email_deliveries
       SET destination=$3, subject=$4, text_body=$4, html_body=$4,
           status=CASE WHEN status IN ('pending','failed','processing') THEN 'cancelled' ELSE status END,
           cancelled_at=CASE WHEN status IN ('pending','failed','processing') THEN now() ELSE cancelled_at END,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, erasedCustomerEmail(customerId), ERASED_PLACEHOLDER],
    );

    await client.query(
      `UPDATE operations.notifications
       SET destination=$3, payload=$4, status=CASE
         WHEN status IN ('queued','retrying') THEN 'cancelled'
         ELSE status
       END, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, erasedCustomerEmail(customerId), { erased: true }],
    );

    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL, properties=$3, anonymous_id=$4
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, { erased: true }, `erased_${customerId}`],
    );

    // Outbox / dead-letter payloads may still hold pre-erasure PII.
    await client.query(
      `UPDATE operations.outbox_events
       SET payload = CASE
         WHEN payload ? 'customerEmail' THEN (payload - 'customerEmail' - 'email' - 'name' - 'phone'
           - 'externalReference' - 'body' - 'subject' - 'billingName')
           || jsonb_build_object('customerId', $2::text, 'erased', true)
         WHEN payload ? 'email' THEN (payload - 'email' - 'name' - 'phone' - 'externalReference'
           - 'body' - 'subject' - 'billingName')
           || jsonb_build_object('customerId', $2::text, 'erased', true)
         WHEN payload ? 'body' OR payload ? 'name' OR payload ? 'billingName' THEN
           (payload - 'email' - 'name' - 'phone' - 'externalReference' - 'body' - 'subject' - 'billingName')
           || jsonb_build_object('customerId', $2::text, 'erased', true)
         ELSE payload
       END
       WHERE merchant_id=$1 AND (
         aggregate_id=$2
         OR (payload->>'customerId') = $2::text
       )`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE operations.dead_letters
       SET payload = jsonb_build_object('erased', true, 'customerId', $1::text)
       WHERE (payload->>'customerId') = $1::text
          OR (payload->'payload'->>'customerId') = $1::text`,
      [customerId],
    );

    await client.query(
      `UPDATE operations.jobs
       SET payload = CASE
         WHEN payload ? 'customerSnapshot' THEN
           (payload - 'customerSnapshot') || jsonb_build_object(
             'customerId', $2::text,
             'customerSnapshot', $3::jsonb,
             'erased', true
           )
         ELSE payload || jsonb_build_object('erased', true)
       END,
       status = CASE
         WHEN status IN ('pending','retry') AND job_type='generate_receipt' THEN 'cancelled'
         ELSE status
       END
       WHERE merchant_id=$1 AND (payload->>'customerId') = $2::text`,
      [merchantId, customerId, JSON.stringify(anonymizedCustomerSnapshot(customerId))],
    );

    await client.query(
      `UPDATE operations.document_manifests
       SET metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('erased', true)
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async scrubProvider(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email=$3, name=$4, external_reference=$5, updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId, erasedCustomerEmail(customerId), erasedCustomerName(), erasedExternalReference(customerId)],
    );
  }

  private async scrubDocuments(merchantId: string, customerId: string): Promise<void> {
    const manifests = await transaction(async (client) => {
      const result = await client.query<{ object_key: string; document_type: string; metadata: Record<string, unknown> }>(
        `SELECT object_key, document_type, metadata FROM operations.document_manifests
         WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      return result.rows;
    });

    for (const manifest of manifests) {
      const redacted = this.redactedDocumentBody(manifest.document_type, customerId, manifest.metadata);
      const body = JSON.stringify(redacted);
      await objectStore.putObject(DOCUMENT_BUCKET, manifest.object_key, body, Buffer.byteLength(body), {
        'Content-Type': 'application/json',
      });
      const checksum = createHash('sha256').update(body).digest('hex');
      await transaction(async (client) => {
        await client.query(
          `UPDATE operations.document_manifests
           SET checksum=$2, metadata=COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('erased', true)
           WHERE object_key=$1`,
          [manifest.object_key, checksum],
        );
      });
    }

    // Customer import objects are keyed by import id and may not have customer_id on the manifest.
    const imports = await transaction(async (client) => {
      const result = await client.query<{ object_key: string }>(
        `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1`,
        [merchantId],
      );
      return result.rows;
    });
    for (const row of imports) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, row.object_key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
        const raw = Buffer.concat(chunks).toString('utf8');
        if (!raw.includes(customerId)) continue;
        const body = JSON.stringify({ erased: true, customerId });
        await objectStore.putObject(DOCUMENT_BUCKET, row.object_key, body, Buffer.byteLength(body), {
          'Content-Type': 'application/json',
        });
        const checksum = createHash('sha256').update(body).digest('hex');
        await transaction(async (client) => {
          await client.query(
            `UPDATE operations.document_manifests
             SET checksum=$2, customer_id=COALESCE(customer_id,$3),
                 metadata=COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('erased', true)
             WHERE object_key=$1`,
            [row.object_key, checksum, customerId],
          );
        });
      } catch {
        // Object may already be gone; continue.
      }
    }
  }

  private redactedDocumentBody(
    documentType: string,
    customerId: string,
    metadata: Record<string, unknown>,
  ): Record<string, unknown> {
    if (documentType === 'receipt') {
      return {
        receiptNumber: metadata.paymentId ?? customerId,
        issuedAt: new Date().toISOString(),
        customer: anonymizedCustomerSnapshot(customerId),
        amount: null,
        currency: null,
        erased: true,
      };
    }
    if (documentType === 'invoice') {
      return {
        invoiceId: metadata.invoiceId ?? null,
        number: metadata.number ?? null,
        customer: anonymizedCustomerSnapshot(customerId),
        erased: true,
      };
    }
    return { erased: true, customerId, documentType };
  }

  private async scrubProjections(merchantId: string, customerId: string): Promise<void> {
    const redis = this.getRedis();
    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    await redis.del(cacheKey);
    await redis.del(`${cacheKey}:activity`);

    try {
      await searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${merchantId}:${customerId}`,
        refresh: true,
      });
    } catch (error) {
      const status = (error as { meta?: { statusCode?: number } })?.meta?.statusCode;
      if (status !== 404) throw error;
    }
  }
}
"}

