  redisCache: cache,
  searchFound,
  docsWithPii,
  mailMessages: mailBody.messages?.length ?? mailBody.total ?? 0,
  failures,
}, null, 2));

await redis.quit();
await pool.end();
if (failures.length) process.exitCode = 1;
"}

