{"path":"/workspace/source/scripts/erasure-e2e.ts","command":"create","file_text":"const gateway = process.env.GATEWAY_URL ?? 'http://api-gateway:3000';
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';

async function api<T>(path: string, method = 'GET', extra: Record<string, string> = {}): Promise<{ status: number; body: T }> {
  const response = await fetch(`${gateway}${path}`, {
    method,
    headers: { authorization: `Bearer ${apiKey}`, ...extra },
  });
  return { status: response.status, body: await response.json() as T };
}

const list = await api<{ data: Array<{ id: string; email: string; name: string; status: string }> }>('/v1/customers');
const target = list.body.data.find((row) => row.status === 'active');
if (!target) throw new Error('no active customer');

const original = { id: target.id, email: target.email, name: target.name };
const created = await api<{
  id: string; status: string; customerId: string; attempts: number; lastError: string | null;
}>(`/v1/customers/${target.id}/erasure-requests`, 'POST', { 'idempotency-key': `erase-e2e-${target.id}` });

if (created.status !== 202) throw new Error(`create failed: ${JSON.stringify(created)}`);

let final = created.body;
for (let attempt = 0; attempt < 40; attempt += 1) {
  const status = await api<typeof created.body>(`/v1/erasure-requests/${created.body.id}`);
  final = status.body;
  if (final.status === 'completed' || final.status === 'failed') break;
  await new Promise((resolve) => setTimeout(resolve, 250));
}

const after = await api<Record<string, unknown>>(`/v1/customers/${target.id}`);
console.log(JSON.stringify({ original, created: created.body, final, after: after.body }, null, 2));
if (final.status !== 'completed') process.exitCode = 1;
"}

